import{_ as t,H as n,f as i,i as E}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"结束语 | 模式既为人设计，也为Agent设计","description":"","frontmatter":{},"headers":[{"level":2,"title":"遇到问题，回哪一讲查","slug":"遇到问题-回哪一讲查","link":"#遇到问题-回哪一讲查","children":[]},{"level":2,"title":"第一张卡：思路记忆卡 —— 这次为什么这样设计","slug":"第一张卡-思路记忆卡-——-这次为什么这样设计","link":"#第一张卡-思路记忆卡-——-这次为什么这样设计","children":[]},{"level":2,"title":"第二张卡：效果验证卡 —— 改完以后，究竟有没有用","slug":"第二张卡-效果验证卡-——-改完以后-究竟有没有用","link":"#第二张卡-效果验证卡-——-改完以后-究竟有没有用","children":[]},{"level":2,"title":"为什么 Agent 时代的模式和经验记录如此重要","slug":"为什么-agent-时代的模式和经验记录如此重要","link":"#为什么-agent-时代的模式和经验记录如此重要","children":[]},{"level":2,"title":"变化这么快，什么值得教，什么值得学","slug":"变化这么快-什么值得教-什么值得学","link":"#变化这么快-什么值得教-什么值得学","children":[]},{"level":2,"title":"带着自己的问题，继续往下做","slug":"带着自己的问题-继续往下做","link":"#带着自己的问题-继续往下做","children":[]}],"relativePath":"Agent设计模式之美/结束语｜模式既为人设计，也为Agent设计.md","filePath":"Agent设计模式之美/结束语｜模式既为人设计，也为Agent设计.md","lastUpdated":1795486474000}'),a={name:"Agent设计模式之美/结束语｜模式既为人设计，也为Agent设计.md"};function s(p,e,A,l,g,r){return n(),i("div",null,[...e[0]||(e[0]=[E('<h1 id="结束语-模式既为人设计-也为agent设计" tabindex="-1">结束语 | 模式既为人设计，也为Agent设计 <a class="header-anchor" href="#结束语-模式既为人设计-也为agent设计" aria-label="Permalink to &quot;结束语 | 模式既为人设计，也为Agent设计&quot;">​</a></h1><p>你好，我是黄佳。</p><p>课程内容告一段落。本来想在这里聊聊这几个月的心路历程，然而，佳哥的心路历程太过于丰富，想说的太多，反而不知道从哪里讲起。</p><p>于是我想先留下几样实用的干货：一张回查表，两张工作卡。它们是从《Designing AIAgents》的附录整理的，遇到具体问题时，你可以翻出来看看，也可以直接放进项目文档里，作为项目知识的一部分，同时指导人和 Coding Agent。</p><p>这张回查表和两张工作卡能帮我们解决三件事：</p><ul><li><p>接到任务时，知道从哪里查起；</p></li><li><p>作出选择时，能说明为什么；</p></li><li><p>运行以后，能判断这次改动有没有用。</p></li></ul><p>这些事情做起来，课程里的知识就能落地到你的工作了。</p><h2 id="遇到问题-回哪一讲查" tabindex="-1">遇到问题，回哪一讲查 <a class="header-anchor" href="#遇到问题-回哪一讲查" aria-label="Permalink to &quot;遇到问题，回哪一讲查&quot;">​</a></h2><p>遇到问题先说清楚发生了什么，再找对应的模式。</p><p>例如，客户收到了一条错误答复。可能是关键材料没找到，也可能是记录已经过期，还可能是模型读到了正确记录，最后却说错了。都是“答错了”，需要检查的地方并不一样。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Agent%E8%AE%BE%E8%AE%A1%E6%A8%A1%E5%BC%8F%E4%B9%8B%E7%BE%8E/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Agent%E8%AE%BE%E8%AE%A1%E6%A8%A1%E5%BC%8F%E4%B9%8B%E7%BE%8E/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" alt=""></a></p><p>一次失败可能涉及几组模式。我们先沿着那次运行找到具体出错的位置，再比较修法。循序渐进，不用上来就把整套系统推倒重来。</p><h2 id="第一张卡-思路记忆卡-——-这次为什么这样设计" tabindex="-1">第一张卡：思路记忆卡 —— 这次为什么这样设计 <a class="header-anchor" href="#第一张卡-思路记忆卡-——-这次为什么这样设计" aria-label="Permalink to &quot;第一张卡：思路记忆卡 —— 这次为什么这样设计&quot;">​</a></h2><p>设计文档里常能看到这样的描述：“采用检索增强、生成评审和审批门。”模式名称都有了，但后来接手的同事仍然可能看不懂：他们需要知道为什么需要这些安排？当时遇到了什么问题？有没有更简单的办法？记得把这些理由记录下来，对我们回溯过程很有帮助。</p><p>下面这张卡在动手前填写，可以帮你梳理模式选型的思路。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Agent%E8%AE%BE%E8%AE%A1%E6%A8%A1%E5%BC%8F%E4%B9%8B%E7%BE%8E/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Agent%E8%AE%BE%E8%AE%A1%E6%A8%A1%E5%BC%8F%E4%B9%8B%E7%BE%8E/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/2.png" alt=""></a></p><ul><li>思路记忆卡</li></ul><p>不必一次填写很长的内容。有些项目写两句话就够了，更详细的规则、样本和设计图可以链接到其他 Spec。某一项答不上来，也写上动手之前还有什么事情没弄清楚。还没有验证的，就先写准备怎样验证。</p><p>其中重要的是弄明白“各部分怎样接起来”。如果下一步需要原文核对结论，前一步就不能只交摘要。如果两个循环套在一起，就要约定整个任务最多运行多久。如果涉及实际写入，就要明确由谁在写入前检查批准和影响范围。Agent 设计既要解决局部问题，又要着眼于任务组合，更需要着眼于全局优化。</p><h2 id="第二张卡-效果验证卡-——-改完以后-究竟有没有用" tabindex="-1">第二张卡：效果验证卡 —— 改完以后，究竟有没有用 <a class="header-anchor" href="#第二张卡-效果验证卡-——-改完以后-究竟有没有用" aria-label="Permalink to &quot;第二张卡：效果验证卡 —— 改完以后，究竟有没有用&quot;">​</a></h2><p>系统设计好了之后，只是万里长征第一步。用过以后，还要持续观测系统效果，看它究竟发现了哪些问题，有没有引入更多问题，多等的时间是否值得。</p><p>举例来说，给代码修复助手加了一轮评审，哪些问题被解决了，哪些地方反而退步了，这次改动究竟值不值得采用。假设同样 20 个任务，旧版做对 16 个，新版做对 18 个，看起来进步了。逐个核对后却发现，新版修好了 3 个旧问题，同时把 1 个原来正确的任务改错了，那么这次修改的效果就是有待商榷的。</p><p>因此，先选好比较任务：记录好当初促使你修改系统的原因（可能来自于失败案例），原来能正常处理的请求，以及不能出错的重要情况。然后用下面的卡片继续记录效果。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Agent%E8%AE%BE%E8%AE%A1%E6%A8%A1%E5%BC%8F%E4%B9%8B%E7%BE%8E/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Agent%E8%AE%BE%E8%AE%A1%E6%A8%A1%E5%BC%8F%E4%B9%8B%E7%BE%8E/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/3.png" alt=""></a></p><ul><li>效果验证卡</li></ul><p>把这些任务留下来，下次换模型、改规则或调整流程时继续使用。这样，下一次修改就有了可以核对的依据。</p><p>两张卡用过几次以后，可以放在一起回看：哪些模式经常解决你的问题，哪些步骤增加以后很少起作用，哪些错误总发生在同一种交接处。团队自己的经验，就是这样一点点积累起来的。</p><h2 id="为什么-agent-时代的模式和经验记录如此重要" tabindex="-1">为什么 Agent 时代的模式和经验记录如此重要 <a class="header-anchor" href="#为什么-agent-时代的模式和经验记录如此重要" aria-label="Permalink to &quot;为什么 Agent 时代的模式和经验记录如此重要&quot;">​</a></h2><p>那么，为什么 Agent 时代的经验记录如此重要呢？</p><p>因为我们不仅学习方式变了，开发方式也变了，系统开发的执行者也多出来了一个 Agent。</p><p>看下面这张图，我们可以把工作拆成三件事：能做什么、做到哪里、谁来负责。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Agent%E8%AE%BE%E8%AE%A1%E6%A8%A1%E5%BC%8F%E4%B9%8B%E7%BE%8E/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Agent%E8%AE%BE%E8%AE%A1%E6%A8%A1%E5%BC%8F%E4%B9%8B%E7%BE%8E/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/4.png" alt=""></a></p><p>Agent 越来越能读需求、写代码、调用工具，但能力变强，不代表它会自动记住整个任务的来龙去脉，也不代表它能替我们承担后果。能力可以交给 Agent，状态需要可靠地保存，责任仍要落实到人和组织。</p><p>人做项目，常常把进度和理由记在脑子里，交接时再补几句。但多个 Agent 并行工作，或者换一个会话继续任务，就不能总靠重新读代码、猜测之前的意图。哪些已经完成，哪些还没验证，当初为什么这样选，都需要留下人和 Agent 都能读懂、核对的记录。</p><p>责任也一样。给 Agent 一个工具，并不是让它随意使用。哪些操作可以直接执行，哪些必须检查或请人批准，失败后由谁接手，都要落实到实际流程中。</p><p>因此我强调模式设计，这个模式不仅仅是给人，也是给 Agent，而我也更强调过程记录的原因：模式设计把进度保存、任务交接、检查和审批安排在合适的位置；过程记录则留下具体的状态、判断和结果。下一次接手任务、换模型或改流程时，我们不必从头猜起，而是能根据已有的理由和证据，决定什么值得保留，什么需要改变。</p><h2 id="变化这么快-什么值得教-什么值得学" tabindex="-1">变化这么快，什么值得教，什么值得学 <a class="header-anchor" href="#变化这么快-什么值得教-什么值得学" aria-label="Permalink to &quot;变化这么快，什么值得教，什么值得学&quot;">​</a></h2><p>前几天，我的书籍编辑秦老师问我，《SDD 实战：规范驱动开发之道》马上安排加印了，有没有勘误信息。</p><p>我说，目前没有需要补充的勘误。不过我也提了一个想法：这本书也许过一年可以考虑第二版。它讲的理论和实践仍然有用，但相关工具和做法变化很快，值得重新检验。</p><p>我们接着聊到，这种知识变化速度会怎样影响书和课程。我的感受是，主要是件好事。可写的东西多，大家也愿意学。但恰恰因为如此，作者更要想清楚什么值得写，读者也要判断什么值得学。我和秦老师说：“需要思考什么是核心价值，不能瞎学瞎写。”</p><p>这句话放在这门课结尾，我觉得也挺合适的。从 Agent 设计的角度，当一个工具换了调用方式，示例就需要更新。一个模型把过去做不好的任务做好了，原来的方案可能需要删掉几步。条件变了，就说明新条件和新选择。在这个年代，变化的速度如此之快，我们的系统一直在演进，我们的思维方式也要跟得上这个变化。</p><p>背后一个更深层次的东西是：每天如此庞大的信息负载，作为一个知识输出者，我要对得起读者，给出真正的价值，大家一起尽量少走弯路。</p><p>幸运的是，很多读者给出了很正面的反馈，让我觉得自己所做的事情是有价值的，方向也是正确的。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Agent%E8%AE%BE%E8%AE%A1%E6%A8%A1%E5%BC%8F%E4%B9%8B%E7%BE%8E/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Agent%E8%AE%BE%E8%AE%A1%E6%A8%A1%E5%BC%8F%E4%B9%8B%E7%BE%8E/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/5.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Agent%E8%AE%BE%E8%AE%A1%E6%A8%A1%E5%BC%8F%E4%B9%8B%E7%BE%8E/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Agent%E8%AE%BE%E8%AE%A1%E6%A8%A1%E5%BC%8F%E4%B9%8B%E7%BE%8E/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/6.png" alt=""></a></p><ul><li>大家的鼓励一直是我前进的动力</li></ul><p>然而，我不觉得知识的输出在 AI 时代变得容易。写这门课的过程中，一个体会挥之不去：知识多，和用户学得进去，是两回事。</p><p>专栏编辑宇新也提醒过我，很多段落内容有深度，但信息挤得太满，影响了阅读体验。我自己回头读，也觉得累。</p><p>AI 很容易帮我们把一份提纲扩成一篇文章，它不缺补充材料的能力，作者反而要花更多功夫决定聚焦在哪里，如何安排内容详略。该展开的那个动作有没有讲清？多加的知识点，看的人现在用得上吗？如何让文章在有嚼头的基础上清晰易读……这些问题我一直在思考。这里也要感谢一下支持佳哥的朋友们，你们的陪伴和反馈是我持续前行的动力。</p><p>变化快，是继续学习和持续修订的理由。因此，我愿意为下一版继续改写，也希望今天交到你手里的内容，今天就有用。</p><h2 id="带着自己的问题-继续往下做" tabindex="-1">带着自己的问题，继续往下做 <a class="header-anchor" href="#带着自己的问题-继续往下做" aria-label="Permalink to &quot;带着自己的问题，继续往下做&quot;">​</a></h2><p>我会努力，我也希望大家一起努力精进。毕竟，我写出来的东西仍然是我的，而只有你练就的内功才真正是属于你的内力。</p><p>接下来，你可以找一处你的系统或者 Demo 里面你最想改的地方，把第一张卡填起来。改完、验证以后，再填第二张。如果最后发现原来的办法更合适，也把理由留下。这同样是一项有用的结果。</p><p>我希望大家学以致用。读懂一篇文章、在练习里运行一次、替换为自己的数据、承担真实业务，是不同阶段。</p><p>我希望 ADPS 社区继续积累这样的讨论：当时在做什么，遇到了什么问题，为什么选择一种办法，又为什么放弃另一种。用过以后，也欢迎告诉我们哪部分帮上了忙，哪部分没有必要，哪部分仍然解释不了你的系统。</p><p>我希望下面这句话，最终能由使用这套方法的工程师来告诉我、告诉我们的社区：“我们用它发现了原来没看见的问题，并且因此改对了系统。”</p><p>让我们在接下来的实践里继续交流！也欢迎你关注我 2026 年 10 月份即将出版的新书《企业本体论：人人都是 FDE》，在这里，我会把企业的业务流程形成模型，给 Agent 的能力搭建基础设计底座。而相关的极客时间训练营，我也会在未来的几个月内开展。</p><p>那么，我们下个专栏见！最后，希望你抽几分钟时间填下结课问卷，我会认真听取大家的反馈。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Agent%E8%AE%BE%E8%AE%A1%E6%A8%A1%E5%BC%8F%E4%B9%8B%E7%BE%8E/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Agent%E8%AE%BE%E8%AE%A1%E6%A8%A1%E5%BC%8F%E4%B9%8B%E7%BE%8E/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/7.png" alt=""></a></p>',59)])])}const B=t(a,[["render",s]]);export{h as __pageData,B as default};
